arguments.command:
mkdir -p tests/CheckoutPricing.UnitTests/Checkout && cd tests/CheckoutPricing.UnitTests/Checkout
cat > LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_with_a_100_subtotal_pays_95()
    {
        var handler = new CalculatePayableTotalHandler();

        var total = handler.Handle(new CalculatePayableTotal(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, total);
    }
}
E
cd ../../../src
echo 'namespace CheckoutPricing.Domain;

public enum CustomerTier { Gold }' > CheckoutPricing.Domain/CustomerTier.cs
echo 'using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculatePayableTotal(CustomerTier Tier, decimal Subtotal);' > CheckoutPricing.Application/CalculatePayableTotal.cs
echo 'namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotal command) => command.Subtotal;
}' > CheckoutPricing.Application/CalculatePayableTotalHandler.cs
cd .. && dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -E "error|Failed|Expected|Actual|Passed!|Failed!" | head

